        // head and can never match).
        latestVerdictRecord: function (n, headSha) {
            if (!headSha || !providerStub._verdictRecords) return null;
            return providerStub._verdictRecords[n] || null;
        },
        _prs: {},
        _status: {},
        _reviews: {},
        _threads: {},
        _verdictRecords: {}
