        var fresh = srcMod2.query({
            query: { type: 'issue', labels: ['ai_developed'], notPrLabels: ['ai_pr_reviewed'] }
        }, { repoInfo: { owner: 'a', repo: 'b' } });
        assert.equal(fresh.length, 1, 'unreviewed PR matches');
    });

