        var srcMod = load({
            github_search_issues: function () {
                return { items: [
                    { number: 9, labels: [{ name: 'agent:dev' }] },
                    { number: 5, labels: [{ name: 'agent:dev' }] },
                    { number: 3, labels: [{ name: 'agent:dev' }] }
