            }
        });
        var items = srcMod.query({
            query: { type: 'issue', labels: ['agent:dev'] }, limit: 2
        }, { repoInfo: { owner: 'a', repo: 'b' } });
        assert.equal(items.map(function (i) { return i.key; }).join(','), 'gh-3,gh-5',
