        assert.ok(!dispatched(sm.capturedCliCommands), 'below the watermark — no parallel arm');
        assert.equal(sm.capturedPrLabelAdds.length, 0, 'the holder keeps the only slot');
        assert.ok(sm.capturedLogs.some(function (l) {
