        if (extra) { for (var k in extra) { if (extra.hasOwnProperty(k)) it[k] = it[k] = extra[k]; } }
        return it;
    }

    function prRest(n, labels) {
        return { number: n, labels: labels.map(function (l) { return { name: l}; }),
