        // Per-PR conveyor state.
        var st = {};
        prNumbers.forEach(function (n) {
            st[n] = { phase: 'waiting', until: 0, refreshed: 0 }; // waiting|validating|green|refresh
        });
        var merges = [];
        var now = 0;
        var guard = 0;

        function src() {
            var open = [];
            var statuses = {};
