                // otherwise BLOCKED (fresh head, required checks pending) —
                // both are not-CLEAN/not-BEHIND shapes the real rule uses.
                statuses[n] = { number: n, state: 'OPEN',
                    mergeState: s.phase === 'refresh' ? 'BEHIND' : 'BLOCKED', mergeable: true };
