            captureConsole: true,
            github: {
                items: [prItem(2, { branch: 'ai/gh-2', headSha: 'sha2', author: 'ai-teammate' })],
                // Depth 2 < default watermark 3.
                prList: [prRest(1, ['pr_approved', 'ai_validating']),
                         prRest(2, ['pr_approved'])],
                prComments: []
